const crypto = require('crypto');
const { FIXED_REFERENCE_MOMENT } = require('./db');
const { getCourseRevision } = require('./utils');

function authMiddleware(db) {
  const findTokenStmt = db.prepare(`
    SELECT t.token, t.user_id, u.id, u.name, u.email, u.role
    FROM tokens t
    JOIN users u ON t.user_id = u.id
    WHERE t.token = ?
  `);

  return (req, res, next) => {
    const authHeader = req.headers['authorization'];
    if (!authHeader) {
      return res.status(401).json({ error: 'Authentication required: missing Authorization header' });
    }

    const parts = authHeader.split(' ');
    const token = parts.length === 2 && /^Bearer$/i.test(parts[0]) ? parts[1] : parts[0];

    if (!token) {
      return res.status(401).json({ error: 'Authentication required: missing token' });
    }

    const user = findTokenStmt.get(token);
    if (!user) {
      return res.status(401).json({ error: 'Unauthorized: invalid or expired session token' });
    }

    req.user = {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role
    };
    req.token = token;
    next();
  };
}

function requireRole(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden: insufficient permissions' });
    }
    next();
  };
}

const requireInstructor = requireRole('instructor');
const requireStaff = requireRole('instructor', 'teaching_assistant');
const requireStudent = requireRole('student');

function handleLogin(db, req, res) {
  const { email, password } = req.body || {};
  if (!email || typeof email !== 'string' || !password || typeof password !== 'string') {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  const user = db.prepare('SELECT id, name, email, role, password FROM users WHERE email = ?').get(email.trim().toLowerCase());
  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  const token = crypto.randomBytes(32).toString('hex');
  db.prepare('INSERT INTO tokens (token, user_id, created_at) VALUES (?, ?, ?)').run(
    token,
    user.id,
    FIXED_REFERENCE_MOMENT
  );

  return res.json({
    token,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role
    }
  });
}

function handleLogout(db, req, res) {
  if (!req.user) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Revoke ALL tokens for this account
  db.prepare('DELETE FROM tokens WHERE user_id = ?').run(req.user.id);

  return res.json({
    success: true,
    message: 'All active sessions for this account have been revoked'
  });
}

function handleMe(db, req, res) {
  if (!req.user) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const course = db.prepare('SELECT id, title, instructor_id, revision FROM courses WHERE id = ?').get('BIO-214');
  return res.json({
    user: req.user,
    course: course || { id: 'BIO-214', title: 'Ecology and Field Methods', revision: 0 }
  });
}

module.exports = {
  authMiddleware,
  requireRole,
  requireInstructor,
  requireStaff,
  requireStudent,
  handleLogin,
  handleLogout,
  handleMe
};

const { computeInputHash, validateOperationId, parseExpectedRevision, getCourseRevision } = require('./utils');
const { FIXED_REFERENCE_MOMENT } = require('./db');

/**
 * Validates operation_id and expected_revision for write operations,
 * and checks if an existing receipt matches or conflicts.
 * 
 * Returns:
 * - { replay: true } if exact match was found and response has already been sent
 * - { error: true } if validation or conflict occurred and error response has been sent
 * - { operationId, expectedRevision, currentRevision, inputHash } if request is valid and new to execute
 */
function checkIdempotencyAndRevision(db, req, res, options = { checkRevision: true, courseId: 'BIO-214' }) {
  const operationIdRaw = (req.body && req.body.operation_id) || req.headers['x-operation-id'] || req.headers['idempotency-key'];
  const opCheck = validateOperationId(operationIdRaw);
  if (!opCheck.valid) {
    const errBody = { error: opCheck.error };
    res.status(400).json(errBody);
    return { error: true };
  }
  const operationId = opCheck.operationId;
  const inputHash = computeInputHash(req.method, req.path, req.body);

  // Check if operation receipt exists
  const existingReceipt = db.prepare('SELECT * FROM operation_receipts WHERE operation_id = ?').get(operationId);
  if (existingReceipt) {
    if (existingReceipt.user_id !== req.user.id) {
      const errBody = { error: 'Operation identifier belongs to another user' };
      res.status(409).json(errBody);
      return { error: true };
    }
    if (existingReceipt.method !== req.method.toUpperCase() || existingReceipt.path !== req.path || existingReceipt.input_hash !== inputHash) {
      const errBody = { error: 'Operation identifier reused for different input or target' };
      res.status(409).json(errBody);
      return { error: true };
    }
    // Exact replay: return saved response
    res.status(existingReceipt.response_status).json(JSON.parse(existingReceipt.response_body));
    return { replay: true };
  }

  // Check revision if required
  let expectedRevision = null;
  const currentRevision = getCourseRevision(db, options.courseId);

  if (options.checkRevision) {
    const revisionRaw = (req.body && req.body.expected_revision !== undefined) ? req.body.expected_revision : req.headers['x-expected-revision'];
    const revCheck = parseExpectedRevision(revisionRaw);
    if (!revCheck.valid) {
      const errBody = { error: revCheck.error, current_revision: currentRevision };
      saveReceipt(db, req.user.id, operationId, req.method, req.path, inputHash, 400, errBody);
      res.status(400).json(errBody);
      return { error: true };
    }
    expectedRevision = revCheck.revision;

    if (expectedRevision !== currentRevision) {
      const errBody = {
        error: 'Stale revision: another user or tab has updated the course data. Please refresh and retry.',
        expected_revision: expectedRevision,
        current_revision: currentRevision
      };
      // Save stale failure receipt so exact replay returns same failure
      saveReceipt(db, req.user.id, operationId, req.method, req.path, inputHash, 409, errBody);
      res.status(409).json(errBody);
      return { error: true };
    }
  }

  return {
    valid: true,
    operationId,
    expectedRevision,
    currentRevision,
    inputHash
  };
}

function saveReceipt(db, userId, operationId, method, path, inputHash, status, responseBodyObj) {
  try {
    const stmt = db.prepare(`
      INSERT OR REPLACE INTO operation_receipts (
        user_id, operation_id, method, path, input_hash, response_status, response_body, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);
    stmt.run(
      userId,
      operationId,
      method.toUpperCase(),
      path,
      inputHash,
      status,
      JSON.stringify(responseBodyObj),
      FIXED_REFERENCE_MOMENT
    );
  } catch (err) {
    console.error('Failed to save operation receipt:', err);
  }
}

function sendAndRecord(db, req, res, status, data, operationContext) {
  if (operationContext && operationContext.operationId) {
    saveReceipt(
      db,
      req.user.id,
      operationContext.operationId,
      req.method,
      req.path,
      operationContext.inputHash,
      status,
      data
    );
  }
  return res.status(status).json(data);
}

module.exports = {
  checkIdempotencyAndRevision,
  saveReceipt,
  sendAndRecord
};

function calculateStudentOutcomes(db, targetStudentId = null) {
  // Get all enrolled students
  let studentsQuery = `
    SELECT u.id, u.name, u.email
    FROM users u
    JOIN enrollments e ON u.id = e.user_id
    WHERE e.course_id = 'BIO-214' AND e.kind = 'student'
  `;
  const params = [];
  if (targetStudentId) {
    studentsQuery += ' AND u.id = ?';
    params.push(targetStudentId);
  }
  studentsQuery += ' ORDER BY u.name ASC';

  const students = db.prepare(studentsQuery).all(...params);

  // Get all published assessments
  const publishedAssessments = db.prepare(`
    SELECT a.id, a.title, a.status, a.opens_at, a.due_at, a.duration_minutes, a.max_attempts
    FROM assessments a
    WHERE a.course_id = 'BIO-214' AND a.status = 'published'
    ORDER BY a.id ASC
  `).all();

  // Get items to calculate maximum points for each assessment
  const items = db.prepare(`
    SELECT id, assessment_id, points
    FROM items
  `).all();

  const maxPointsMap = {};
  for (const a of publishedAssessments) {
    maxPointsMap[a.id] = 0;
  }
  for (const it of items) {
    if (maxPointsMap[it.assessment_id] !== undefined) {
      maxPointsMap[it.assessment_id] += it.points;
    }
  }

  // Get policy weights
  const weightsRows = db.prepare(`
    SELECT assessment_id, weight_percent
    FROM assessment_weights
    WHERE course_id = 'BIO-214'
  `).all();
  const weightsMap = {};
  for (const w of weightsRows) {
    weightsMap[w.assessment_id] = w.weight_percent;
  }

  // Get exceptions
  const exceptionsRows = db.prepare(`
    SELECT student_id, assessment_id, excused, reason
    FROM student_exceptions
    WHERE course_id = 'BIO-214'
  `).all();
  const exceptionsMap = {};
  for (const ex of exceptionsRows) {
    exceptionsMap[`${ex.student_id}_${ex.assessment_id}`] = ex;
  }

  // Get all attempts
  const allAttempts = db.prepare(`
    SELECT id, assessment_id, student_id, status, started_at, submitted_at, feedback_status, objective_score, rubric_score
    FROM attempts
    ORDER BY started_at DESC, id DESC
  `).all();

  // Map most recent attempt for (student_id, assessment_id)
  const mostRecentAttemptMap = {};
  for (const att of allAttempts) {
    const key = `${att.student_id}_${att.assessment_id}`;
    if (!mostRecentAttemptMap[key]) {
      mostRecentAttemptMap[key] = att;
    }
  }

  // Build outcomes ledger for each student
  const ledger = students.map(student => {
    const assessmentCells = publishedAssessments.map(assessment => {
      const weight = weightsMap[assessment.id] !== undefined ? weightsMap[assessment.id] : 0;
      const maxPoints = maxPointsMap[assessment.id] || 0;
      const exKey = `${student.id}_${assessment.id}`;
      const exception = exceptionsMap[exKey];
      const isExcused = !!(exception && exception.excused === 1);
      const attempt = mostRecentAttemptMap[exKey];

      let state = 'missing'; // 'missing', 'pending', 'released', 'excused', 'unweighted'
      let awardedPoints = null;
      let attemptId = attempt ? attempt.id : null;
      let attemptStatus = attempt ? attempt.status : null;
      let feedbackStatus = attempt ? attempt.feedback_status : null;

      if (isExcused) {
        state = 'excused';
      } else if (weight === 0) {
        state = 'unweighted';
        if (attempt && attempt.feedback_status === 'released') {
          awardedPoints = (attempt.objective_score || 0) + (attempt.rubric_score || 0);
        }
      } else if (!attempt) {
        state = 'missing';
      } else if (attempt.feedback_status === 'released') {
        state = 'released';
        awardedPoints = (attempt.objective_score || 0) + (attempt.rubric_score || 0);
      } else {
        state = 'pending';
      }

      return {
        assessment_id: assessment.id,
        assessment_title: assessment.title,
        weight,
        max_points: maxPoints,
        state,
        excused: isExcused,
        excuse_reason: isExcused ? exception.reason : null,
        attempt_id: attemptId,
        attempt_status: attemptStatus,
        feedback_status: feedbackStatus,
        awarded_points: awardedPoints
      };
    });

    // Compute final outcome
    const included = assessmentCells.filter(c => !c.excused && c.weight > 0);
    let finalPercentage = null;
    let finalStatus = 'unavailable'; // 'calculated', 'pending', 'unavailable'
    let explanation = '';

    if (included.length === 0) {
      finalStatus = 'unavailable';
      explanation = 'No weighted assessments included in grade calculation';
    } else {
      const hasMissing = included.some(c => c.state === 'missing');
      const hasPending = included.some(c => c.state === 'pending');

      if (hasMissing || hasPending) {
        finalStatus = 'pending';
        const pendingNames = included.filter(c => c.state === 'missing' || c.state === 'pending').map(c => c.assessment_title);
        explanation = `Final grade pending: awaiting completion or release of ${pendingNames.join(', ')}`;
      } else {
        // All included are released
        let sumWeights = 0;
        let sumWeightedScores = 0;

        for (const c of included) {
          sumWeights += c.weight;
          const ratio = c.max_points > 0 ? (c.awarded_points / c.max_points) : 0;
          sumWeightedScores += c.weight * ratio;
        }

        if (sumWeights > 0) {
          finalPercentage = Number((100 * sumWeightedScores / sumWeights).toFixed(2));
          finalStatus = 'calculated';
          explanation = `Calculated from ${included.length} released assessment(s) totaling ${sumWeights.toFixed(2)}% included weight`;
        } else {
          finalStatus = 'unavailable';
          explanation = 'Total included weight is zero';
        }
      }
    }

    return {
      student_id: student.id,
      name: student.name,
      email: student.email,
      assessments: assessmentCells,
      final_percentage: finalPercentage,
      final_status: finalStatus,
      explanation
    };
  });

  return {
    assessments: publishedAssessments.map(a => ({
      id: a.id,
      title: a.title,
      weight: weightsMap[a.id] !== undefined ? weightsMap[a.id] : 0,
      max_points: maxPointsMap[a.id] || 0
    })),
    policy_weights: weightsMap,
    ledger
  };
}

module.exports = {
  calculateStudentOutcomes
};

